#!/usr/bin/env python3
"""Tiny notes CLI: add TEXT / show"""
import sys
from datetime import date

NOTES = "notes.txt"

def main():
    cmd, rest = sys.argv[1], sys.argv[2:]
    if cmd == "add" and rest:
        with open(NOTES, "a") as f:
            f.write(f"{date.today()} {' '.join(rest)}\n")
    elif cmd == "show":
        with open(NOTES) as f:
            sys.stdout.write(f.read())
    else:
        sys.exit("usage: notes.py add TEXT | notes.py show")

main()

#!/usr/bin/env python3
"""Tiny notes CLI: add TEXT / show / count"""
import os
import sys
from datetime import date

NOTES = os.path.join(os.path.dirname(os.path.abspath(__file__)), "notes.txt")

def read_lines():
    try:
        with open(NOTES) as f:
            return f.read().splitlines()
    except FileNotFoundError:
        return []

def main():
    cmd, rest = sys.argv[1], sys.argv[2:]
    if cmd == "add" and rest:
        with open(NOTES, "a") as f:
            f.write(f"{date.today()} {' '.join(rest)}\n")
    elif cmd == "show":
        for line in reversed(read_lines()):
            print(line)
    elif cmd == "count":
        print(len(read_lines()))
    else:
        sys.exit("usage: notes.py add TEXT | notes.py show | notes.py count")

main()

